begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
-- A second household shares the route but remains independently authorized.
create temp table family_route(run_id uuid,stop_id uuid,version integer,own_ids uuid[],foreign_id uuid,first_portal uuid,second_portal uuid);
insert into family_route select null,null,null,null,null,null,null;
do $$declare e uuid;h uuid:=gen_random_uuid();reg uuid:=gen_random_uuid();c uuid:=gen_random_uuid();begin
 select id into e from app_private.events where slug='duindorp-halloween-2026';
 insert into app_private.households(id,label,primary_contact_user_id) values(h,'Ander oefengezin','b0000000-0000-0000-0000-000000000001');
 insert into app_private.household_members(household_id,user_id,relation_role) values(h,'b0000000-0000-0000-0000-000000000001','owner');
 insert into app_private.registrations(id,event_id,household_id,status,reference) values(reg,e,h,'submitted','ISOLATED-'||reg);
 insert into app_private.children(id,household_id,first_name,age_at_event) values(c,h,'Ander oefenkind',8);
 insert into app_private.registration_children(event_id,registration_id,child_id,unit_price_cents) values(e,reg,c,0);
 insert into app_private.group_registrations(group_id,registration_id,assignment_revision,published_at) values('23000000-0000-0000-0000-000000000002',reg,1,now());
end $$;
select set_config('request.jwt.claims','{"sub":"c0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
update family_route set run_id=(api.run_start('23000000-0000-0000-0000-000000000002',array(select rc.id from app_private.registration_children rc join app_private.group_registrations gr on gr.registration_id=rc.registration_id where gr.group_id='23000000-0000-0000-0000-000000000002' and gr.superseded_at is null),1,'family-start','family-start')->>'runId')::uuid;
update family_route f set stop_id=r.current_stop_id,version=r.version from app_private.group_runs r where r.id=f.run_id;
update family_route f set first_portal=p.portal_id from app_private.run_stops s join app_private.route_plan_stops p on p.id=s.plan_stop_id where s.id=f.stop_id;
select lives_ok($$select api.run_arrive_and_advance((select run_id from family_route),(select stop_id from family_route),(select version from family_route),'TEST-PORTAL-01-TOKEN',(select jsonb_object_agg(id::text,'skipped') from app_private.run_participants where run_id=(select run_id from family_route) and attendance='present'),'family-arrival')$$,'all present children receive an arrival when everyone stays outside');
select is((select count(*) from app_private.run_stop_arrivals where run_id=(select run_id from family_route)),6::bigint,'six present children get six immutable arrival facts');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
update family_route f set own_ids=array(select p.id from app_private.run_participants p join app_private.registration_children rc on rc.id=p.registration_child_id join app_private.registrations r on r.id=rc.registration_id where p.run_id=f.run_id and app_private.is_household_member(r.household_id,auth.uid())),foreign_id=(select p.id from app_private.run_participants p join app_private.registration_children rc on rc.id=p.registration_child_id join app_private.registrations r on r.id=rc.registration_id where p.run_id=f.run_id and not app_private.is_household_member(r.household_id,auth.uid()) limit 1),version=(select version from app_private.group_runs where id=f.run_id);
select throws_ok($$select api.run_end_early((select run_id from family_route),(select version from family_route),array[(select foreign_id from family_route)],'Niet ons kind','family-forbidden')$$,'42501','NOT_AUTHORIZED','a parent cannot depart a different household');
select lives_ok($$select api.run_end_early((select run_id from family_route),(select version from family_route),(select own_ids from family_route),'Eigen gezin rondt af','family-departure')$$,'the own household can finish calmly');
select is((select status::text from app_private.group_runs where id=(select run_id from family_route)),'live','another family keeps its route');
select is(api.group_snapshot('23000000-0000-0000-0000-000000000002')->'run'->>'ownEveningFinished','true','the own parent sees a personal farewell');
select is(api.group_snapshot('23000000-0000-0000-0000-000000000002')->'run'->'currentStop','null'::jsonb,'a departed household no longer receives future private addresses');
select lives_ok($$select api.portal_thanks_save('duindorp-halloween-2026',(select first_portal from family_route),'beautiful')$$,'an arrived family may thank the gate even if the experience was skipped');
select lives_ok($$select api.portal_thanks_save('duindorp-halloween-2026',(select first_portal from family_route),'welcome')$$,'a new message replaces the existing thanks');
select is((select count(*) from app_private.portal_thanks),1::bigint,'editing does not count twice');
select set_config('request.jwt.claims','{"sub":"c0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
update family_route f set stop_id=r.current_stop_id,version=r.version from app_private.group_runs r where r.id=f.run_id;
update family_route f set second_portal=p.portal_id from app_private.run_stops s join app_private.route_plan_stops p on p.id=s.plan_stop_id where s.id=f.stop_id;
select throws_ok($$select api.run_update_participant((select run_id from family_route),(select stop_id from family_route),(select own_ids[1] from family_route),'visited',(select version from family_route),1,null)$$,'23514','INVALID_ATTENDANCE','a departed child cannot gain a later seal through an old status mutation');
select lives_ok($$select api.run_arrive_and_advance((select run_id from family_route),(select stop_id from family_route),(select version from family_route),'TEST-PORTAL-02-TOKEN',(select jsonb_object_agg(id::text,'visited') from app_private.run_participants where run_id=(select run_id from family_route) and attendance='present'),'family-second-arrival')$$,'the remaining household may reach its next gate');
select is((select count(*) from app_private.poortenboek_passport_seals where run_id=(select run_id from family_route)),7::bigint,'departed children retain only their first seal; the remaining child has two');
select set_config('request.jwt.claims','{"sub":"a0000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
select throws_ok($$select api.portal_thanks_save('duindorp-halloween-2026',(select second_portal from family_route),'treats')$$,'42501','NOT_AUTHORIZED','a family cannot thank gates reached after its departure');
select throws_ok($$select api.portal_thanks_snapshot('duindorp-halloween-2026','house',(select first_portal from family_route))$$,'42501','NOT_AUTHORIZED','a parent cannot read the gate team aggregate');
select set_config('request.jwt.claims','{"sub":"f0000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
select is(api.portal_thanks_snapshot('duindorp-halloween-2026','admin')->>'familyCount','1','organizer totals count one family');
select ok(not(api.portal_thanks_snapshot('duindorp-halloween-2026','admin')::text like '%householdId%'),'organizer thanks do not reveal family identifiers');
select * from finish();
rollback;
